async function waitOut(r) {
  if (!r) { return ''; }
  if (r.status === 'running' && r.sessionId) {
    for (let i = 0; i < 20; i++) {
      let p = null;
      try { p = await process({ action: 'poll', sessionId: r.sessionId, timeout: 10000 }); } catch (e) { break; }
      if (p && p.status && p.status !== 'running') { r = p; break; }
    }
    try { const lg = await process({ action: 'log', sessionId: r.sessionId }); if (lg) { if (lg.output !== undefined) { return String(lg.output); } if (lg.log !== undefined) { return String(lg.log); } return JSON.stringify(lg); } } catch (e) {}
  }
  if (r.aggregated !== undefined) { return String(r.aggregated); }
  if (r.output !== undefined) { return String(r.output); }
  if (r.stdout !== undefined) { return String(r.stdout); }
  if (r.tail !== undefined) { return String(r.tail); }
  return JSON.stringify(r);
}
const res = await exec({ command: 'cd ~/stock_swing && . venv/bin/activate && python scripts/log_sector_rotation_shadow.py 2>&1; echo EXIT_CODE=$?', timeoutSeconds: 260, yieldMs: 270000 });
const outStr = await waitOut(res);
const m = outStr.match(/EXIT_CODE=(\d+)/);
if (m && m[1] === '0') { return {}; }
return { notify: '❌ sector_rotation_shadow 実行エラー\n' + outStr.slice(-600) };
